catch (InvalidOperationException)
                    {
                        // No connected peers available, disconnect
                        connectedPeer = null;
                        RaiseLogEntry(new LogEventArgs("[Phinix] Connection attempt ended: no server address responded.", LogLevel.WARNING));
                        Disconnect();
                    }

throw new ArgumentOutOfRangeException(
                    nameof(port),
                    port,
                    $"Cannot assign a port below {IPEndPoint.MinPort} or above {IPEndPoint.MaxPort}."
                );

catch (SocketException)
            {
                // Couldn't contact a DNS server, set output to nothing and return a failure
                addresses = null;
                return false;
            }

catch(Exception error)
                    {
                        Verse.Log.Warning("[Phinix] ManagedInventoryUnavailable; startup discovery is retained; refresh management to retry. " + error.GetType().Name);
                        if(Prefs.DevMode) Verse.Log.Warning(error.ToString());
                    }

catch(Exception error)
                {
                    Verse.Log.Warning("[Phinix] ManagedStartupUnavailable; built-in discovery continues. " + error.GetType().Name);
                    if(Prefs.DevMode) Verse.Log.Warning(error.ToString());
                    extensionControls?.Dispose(); extensionControls=null;
                    managedExtensionRuntime?.Dispose();
                }

catch(Exception error)
            {
                StopExtensions();
                Verse.Log.Error("[Phinix] ExtensionStartupFailed: " + error);
            }

catch (Exception ex)
                        {
                            if (settingsProviderFailures.Add(panel.GetType().FullName)) Verse.Log.Warning("[Phinix] Settings panel failed: " + ex);
                            ClientWidgets.Label(listing.GetRect(32), "Phinix_shell_providerFailed".Translate(), HostThemeDrawing.Current, true);
                        }

catch (Exception ex)
            {
                connectionAttemptPending = false;
                connectionAttemptFailed = true;
                Verse.Log.Error($"[Phinix] Could not connect to {address}:{port}: {ex}");
                mainThreadDispatcher?.Enqueue(() => windowService?.Open(new Dialog_MessageBox(
                    title: "Phinix_error_connectionFailedTitle".Translate(),
                    text: "Phinix_error_connectionFailedMessage".Translate(address, port))));
            }

catch (Exception ex)
            {
                // Assembly.Location can throw in some contexts; log and return null
                Verse.Log.Warning($"[Phinix] ResolveModPackageId failed for assembly '{assembly.FullName}': {ex.Message}");
            }

catch(Exception error)
            {
                lock(gate) { known=false; Changed(); }
                try { diagnostic?.Invoke(error); } catch { }
                return new ClientExtensionControlResult(false,"ManagedModuleSettingsWriteFailed");
            }

catch
            {
                lock(gate) { if(known) { known=false; Changed(); } }
                throw;
            }

catch (Exception ex)
            {
                Report("LinkOpenUnavailable:" + ex.GetType().Name, uri.Host);
                return ClientLinkOpenResult.Unavailable;
            }

catch(Exception error)
                {
                    record.Complete(ClientTaskState.Failed,"CallbackFailed");
                    Report("Main-thread callback failed: owner="+record.ModuleId+", task="+record.Id+", exception="+error.GetType().Name,LogLevel.ERROR);
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"Message handler {handler.GetType().FullName} threw for outgoing text: {ex}", LogLevel.ERROR));
                    // Dispatch may already have occurred; never try another handler.
                    throw;
                }

catch (Exception error)
                {
                    RaiseLogEntry(new LogEventArgs("Message submission failed in " + handler.GetType().FullName + ": " + error, LogLevel.ERROR));
                    return false;
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"[Phinix] Outgoing command handler {handler.GetType().FullName} threw: {ex}", LogLevel.ERROR));
                    // Dispatch may already have occurred; never try another handler.
                    throw;
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"[Phinix] Outgoing item handler {handler.GetType().FullName}.CanHandle threw: {ex}", LogLevel.ERROR));
                    continue;
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"[Phinix] Outgoing item handler {handler.GetType().FullName} threw: {ex}", LogLevel.ERROR));
                    // Dispatch may already have occurred; never try another handler.
                    throw;
                }

catch (Exception exception)
            {
                RaiseLogEntry(new LogEventArgs($"Failed to deserialize framework packet: {exception.Message}", LogLevel.WARNING));
                return;
            }

catch
            {
                admissionControl.RejectMalformed(packet.SessionId);
                negotiationTimer.Stop();
                RaiseLogEntry(new LogEventArgs("Malformed framework control; reconnect required, no protocol fallback.", LogLevel.WARNING));
                showSystemMessage("Phinix_framework_controlMalformed");
                return;
            }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"Message handler {handler.GetType().FullName} threw for '{currentMessage.MessageType}': {ex}",
                        LogLevel.ERROR));
                    continue;
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"Message renderer {renderer.GetType().FullName} threw for '{currentMessage.MessageType}': {ex}",
                        LogLevel.ERROR));
                    continue;
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"Command handler {handler.GetType().FullName} threw for '{currentCommand.MessageType}': {ex}",
                        LogLevel.ERROR));
                    continue;
                }

catch (Exception ex)
                {
                    RaiseLogEntry(new LogEventArgs(
                        $"Item handler {handler.GetType().FullName} threw for '{currentItem.MessageType}': {ex}",
                        LogLevel.ERROR));
                    continue;
                }

catch (Exception ex)
            {
                RaiseLogEntry(new LogEventArgs(
                    $"[Phinix] Failed to send packet type={packet.MessageType}: {ex.Message}",
                    LogLevel.ERROR));
            }

catch (Exception ex)
            {
                reportShutdownWarning($"Failed to dispose framework negotiation timer: {ex}");
            }

catch (Exception ex)
            {
                reportShutdownWarning($"Failed to unregister framework client handlers: {ex}");
            }

catch (Exception error)
            {
                appendExtensionLog("Shutdown log callback failed: " + error.Message, LogLevel.WARNING);
            }

catch (Exception error)
                {
                    Report(fallback, error);
                    next.Add(new Entry<T> { Handle = handle, Api = api, Id = fallback, Label = handle.OwnerId, Failed = true });
                }

catch (Exception ex)
                {
                    if (failedPanels.Add(panel)) Log.Warning("[Phinix] Quick settings measure failed: " + ex);
                    height += 40;
                }

catch (Exception ex)
                {
                    if (failedPanels.Add(panel)) Log.Warning("[Phinix] Quick settings draw failed: " + ex);
                }

catch (Exception ex)
            {
                Client.Instance.Log(new LogEventArgs($"Failed to load settings XML: {ex.Message}", LogLevel.ERROR));
                return null;
            }

catch (Exception e)
                {
                    Client.Instance.Log(new LogEventArgs($"Failed to deserialise ListSetting: {e.Message}", LogLevel.ERROR));
                    return false;
                }

catch(Exception error)
            {
                SetExtensionDisabled(extensionId,previous);
                try { AcceptChanges(); }
                catch(Exception rollback) { throw new AggregateException("Extension module settings recovery failed.",error,rollback); }
                throw;
            }

catch (Exception error)
                {
                    Fail("RenderFailed", error);
                    using (new ClientGuiScope(true)) { Text.Font = GameFont.Small; Text.Anchor = TextAnchor.UpperLeft; Text.WordWrap = true;
                        ClientWidgets.Label(rect, L("failed"), service.theme.Error.ToUnityColor()); }
                }

catch (SqliteException error)
                    {
                        var failure = committing ? DatabaseFailure.OutcomeUnknown :
                            error.SqliteErrorCode == 5 || error.SqliteErrorCode == 6 ? DatabaseFailure.Busy :
                            error.SqliteErrorCode == 11 || error.SqliteErrorCode == 26 ? DatabaseFailure.Corrupt : DatabaseFailure.Unavailable;
                        throw new ClientDatabaseException(failure, committing ? "Database commit could not be confirmed; check this operation before retrying." : "Database operation failed; changes were not committed.", error);
                    }

catch (Exception ex)
                            {
                                hostLog?.Invoke($"Failed to raise chat mention letter: {ex.Message}", LogLevel.WARNING);
                            }

catch (Exception error)
            {
                try { host?.Log?.Invoke("Chat cleanup failed: " + error, LogLevel.WARNING); } catch { }
            }

catch (ArgumentException)
                {
                    hostContext.Log(new LogEventArgs(string.Format("Found existing chat message with key {0} when recalculating messageRectCache. Chat may fail to draw messages with this ID until it's updated again!", chatMessage.MessageId), LogLevel.ERROR));
                }

catch (Exception ex)
                {
                    hostContext.Log(new LogEventArgs("Image download processing failed: " + ex.Message, LogLevel.WARNING));
                }

catch (Exception ex)
            {
                Log?.Invoke($"[PhinixChat] Failed to parse BuiltInChatMessagePayload: {ex.Message}", LogLevel.WARNING);
                // Return a displayable error message instead of letting the exception propagate
                return new FrameworkDisplayMessage
                {
                    MessageId = message?.MessageId ?? Guid.NewGuid().ToString(),
                    SenderUuid = FrameworkProtocol.SystemSenderUuid,
                    Source = "builtin_chat",
                    Text = "[Phinix] Failed to decode incoming chat message.",
                    IsNotice = false
                };
            }

catch
            {
                var failedDialog = deliveryChoiceDialog;
                deliveryChoiceDialog = null; deliveryChoiceOpen = false;
                failedDialog?.Dispose();
                throw;
            }

catch (Exception error)
            {
                fault = "Inventory database unavailable: " + error.Message;
                host?.Log?.Invoke("[Inventory] " + fault, LogLevel.ERROR);
            }

catch (Exception ex)
            {
                host?.Log?.Invoke("[Inventory] Deposit failed: " + ex, LogLevel.ERROR);
                return new InventoryDepositResult { Status = InventoryDepositStatus.Rejected, FailureCode = InventoryFailureCode.InvalidRequest, Reason = ex.Message };
            }

catch (Exception ex)
            {
                host?.Log?.Invoke("[Inventory] Deposit receipt check failed: " + ex, LogLevel.ERROR);
                return new InventoryDepositResult { Status = InventoryDepositStatus.Rejected, FailureCode = InventoryFailureCode.InvalidRequest, Reason = ex.Message };
            }

catch (Exception ex)
            {
                host?.Log?.Invoke("[Inventory] Reservation failed: " + ex, LogLevel.ERROR);
                return new InventoryReservationResult
                {
                    Status = InventoryReservationResultStatus.Rejected,
                    FailureCode = InventoryFailureCode.InvalidRequest,
                    Reason = ex.Message
                };
            }

catch (Exception ex)
            {
                host?.Log?.Invoke("[Inventory] Preview materialization failed: " + ex, LogLevel.WARNING);
                return MaterializationFailure(ex.Message, InventoryFailureCode.CodecUnavailable);
            }

catch (Exception ex)
            {
                foreach (Thing thing in materialized) DiscardUnclaimed(thing);
                host?.Log?.Invoke("[Inventory] Reservation materialization failed: " + ex, LogLevel.ERROR);
                return MaterializationFailure(ex.Message, InventoryFailureCode.CodecUnavailable);
            }

catch (Exception ex)
            {
                host?.Log?.Invoke("[Inventory] Reservation resolution failed: " + ex, LogLevel.ERROR);
                return new InventoryReservationResolutionResult
                {
                    Succeeded = false,
                    FailureCode = InventoryFailureCode.InvalidRequest,
                    Reason = ex.Message
                };
            }

catch (Exception ex)
            {
                reason = "Item could not be restored: " + ex.Message;
                host?.Log?.Invoke("[Inventory] Materialize failed: " + ex, LogLevel.ERROR);
                return false;
            }

catch (Exception ex)
            {
                host?.Log?.Invoke("[Inventory] Delivery failed: " + ex, LogLevel.ERROR);
                InventoryDeliveryResult custody = InventoryDropDelivery.InspectCustody(new[] { thing }, map, spot);
                if (custody.Status == InventoryDeliveryStatus.Rejected)
                    return RestoreRejectedDelivery(thing, ex.Message, out reason);
                reason = "Delivery status is uncertain; reconcile the pending extraction.";
                return false;
            }

catch (Exception ex)
                {
                    host?.Log?.Invoke("[Inventory] Item presentation failed for '" + entry.CodecId + "': " + ex, LogLevel.ERROR);
                }

catch (Exception ex)
                {
                    host?.Log?.Invoke("[Inventory] Source presenter failed for '" + entry.Source + "': " + ex, LogLevel.ERROR);
                }

catch (Exception ex)
            {
                reason = "The item codec could not determine a stack limit: " + ex.Message;
                host?.Log?.Invoke("[Inventory] Stack limit lookup failed: " + ex, LogLevel.ERROR);
            }

catch (ClientDatabaseException error)
            {
                LastError = error.Message;
                if (error.Failure == DatabaseFailure.OutcomeUnknown || error.Failure == DatabaseFailure.Corrupt)
                { Faulted = true; FaultReason = LastError; }
                return false;
            }

catch (Exception) when (!endsWithNewline && reader.Peek() < 0)
                        {
                            // A complete, conflicting record is evidence, never a torn-write exception.
                            InventoryState candidate = null;
                            try { candidate = Parse(line); } catch { }
                            if (candidate != null) throw;
                            ignoredTornTail = true; break;
                        }

catch (Exception error)
                {
                    CheckpointError = "Checkpoint: " + error.GetType().Name + ": " + SafeReason(error);
                    Report(CheckpointError); return false;
                }

catch (Exception error)
            {
                // Never expose full player paths, snapshot contents or payloads.
                Report(report, "[Inventory][Compatibility] History retained; saved proof unavailable: " + error.GetType().Name + ".", true);
                return false;
            }

catch (Exception exception)
            {
                reason = "A safe drop-pod landing cell could not be resolved: " + exception.Message;
                return false;
            }

catch (Exception exception)
            {
                InventoryDeliveryResult custody = InspectCustody(materialized, map, dropSpot);
                custody.Status = custody.Status == InventoryDeliveryStatus.Rejected
                    ? InventoryDeliveryStatus.Rejected
                    : InventoryDeliveryStatus.Uncertain;
                custody.Reason = "Drop-pod delivery threw an exception: " + exception.Message;
                return custody;
            }

catch (Exception exception)
            {
                Verse.Log.Warning("[Phinix][P5Drop] Could not inspect custody: " + exception.GetType().Name);
            }

catch (Exception error)
            {
                try { Shutdown(hostContext); }
                catch (Exception cleanup) { throw new AggregateException(error, cleanup); }
                throw;
            }

catch (Exception error)
            {
                // Dispatch already succeeded; an observer failure must not invite another send.
                try { log?.Invoke("[LegacyAdapter] Chat echo failed after dispatch: " + error, LogLevel.WARNING); } catch { }
            }

catch (Exception error)
                {
                    try { Dispose(); }
                    catch (Exception cleanup) { throw new AggregateException(error, cleanup); }
                    throw;
                }

catch (Exception ex)
            {
                Report($"[LegacyAdapter] Failed to send legacy chat message: {ex.Message}", LogLevel.WARNING);
                return false;
            }

catch (Exception ex)
            {
                Report($"[LegacyAdapter] Error handling legacy chat packet: {ex.Message}", LogLevel.WARNING);
            }

catch (Exception ex)
            {
                Report($"[LegacyAdapter] Failed to unpack {typeof(T).Name}: {ex.Message}", LogLevel.WARNING);
                return;
            }

catch (Exception ex)
            {
                Report($"[LegacyAdapter] Error in {typeof(T).Name} handler: {ex.Message}", LogLevel.WARNING);
            }

catch (Exception ex)
                        {
                            if (!(ex is TradeSendOutcomeUnknownException))
                            {
                                resultApi.CompleteTradeUpdate(payload.TradeId, token, TradeFailureReason.InternalServerError, ex.Message);
                            }
                            throw;
                        }

catch (Exception ex)
            {
                log?.Invoke($"[LegacyAdapter] Error handling legacy trade packet: {ex}", LogLevel.ERROR);
            }

catch (Exception ex)
            {
                log?.Invoke(
                    $"[LegacyAdapter] ConvertFromFrameworkVanillaItemData: item[{index}] failed: {ex}",
                    LogLevel.WARNING);
                return null;
            }

catch (Exception ex)
            {
                log?.Invoke(
                    $"[LegacyAdapter] ConvertFromPayloadJson: item[{index}] ParseJson failed: {ex}",
                    LogLevel.WARNING);
                return null;
            }

catch (StoreValidationException ex)
                {
                    if (ex.Code == "PlanLimit" || ex.Code == "ResolutionLimit") throw;
                    failure = ex;
                    return false;
                }

catch(StoreValidationException ex)
            {
                if(ex.Code=="DeveloperModeRequired") throw new OperationCanceledException("Local import authorization was revoked.");
                throw new ManagedExtensionValidationException(ex.Code,ex);
            }

catch (OperationCanceledException)
                {
                    if (token.IsCancellationRequested)
                    { diagnostics.Event("package.cancelled", "Package", requestId: LastRequestId, managed: expected, snapshot: catalog.SnapshotId, catalogHash: catalog.Sha256); throw; }
                    string code = total.IsCancellationRequested ? "PackageDownloadTimeout" : "PackageUnavailable";
                    diagnostics.Event("package.failed", "Package", code, LastRequestId, managed: expected, snapshot: catalog.SnapshotId, catalogHash: catalog.Sha256);
                    throw new StoreValidationException(code, "Package operation did not complete.") { RequestId = LastRequestId };
                }

catch(Exception ex)
                    {
                        var validation=ex as StoreValidationException;
                        string code=validation?.Code??(ex as ManagedExtensionValidationException)?.Code??"ManagedStoreFailed";
                        var referenceFailure=validation?.ReferenceFailure??(ex as ManagedExtensionValidationException)?.ReferenceFailure;
                        var failure=audit.Failure("managed.operation_failed","ManagedStore",ex,"ManagedStoreFailed");
                        code=failure.Code;
                        outcome=Result(ManagedStoreState.Failed,null,null,null,null,code,failure.RequestId,validation?.LocalIdentity,referenceFailure,contextReasons:failure.ContextReasons);
                    }

catch(Exception)
            {
                // Cancellation marks the token before invoking callbacks; a throwing
                // callback/logger must not prevent terminal stop or other cleanup.
                new RepositoryDiagnostics(log,snapshot.Repository?.Endpoint.SourceId).Event("managed.cancel_callback_failed","ManagedStore","ManagedStoreFailed");
            }

catch(Exception error)
            {
                try { Shutdown(hostContext); }
                catch(Exception cleanup) { throw new AggregateException(error,cleanup); }
                throw;
            }

catch (OperationCanceledException)
                {
                    if (token.IsCancellationRequested)
                    { diagnostics.Event("package.cancelled", "Package", requestId: LastRequestId, package: expected); throw; }
                    string code = total.IsCancellationRequested ? "PackageDownloadTimeout" : "PackageUnavailable";
                    diagnostics.Event("package.failed", "Package", code, LastRequestId, package: expected);
                    throw new StoreValidationException(code, "Package operation did not complete.") { RequestId = LastRequestId };
                }

catch(Exception ex)
            {
                if(texture!=null) UnityEngine.Object.Destroy(texture);
                texture=null;
                try { diagnostic?.Invoke(kind+":"+ex.GetType().Name); } catch { }
            }

catch (OperationCanceledException)
            {
                audit?.Event("repository.task_cancelled");
                lock (gate)
                    if (!disposed && generation == ticket)
                    { running = null; Publish(StoreBrowserState.Cancelled, snapshot.Catalog, null, null, null); }
            }

catch (Exception ex)
            {
                var validation = ex as StoreValidationException;
                if (validation == null && (operation == StoreBrowserState.Installing || operation == StoreBrowserState.Managing) &&
                    (ex is IOException || ex is UnauthorizedAccessException))
                    validation = new StoreValidationException("InstallationStorageFailed", "Filesystem operation failed. Use refresh/recovery before retrying; ownership records and uncertain files were preserved.", ex);
                var failure=audit.Failure("repository.task_failed",operation.ToString(),validation??ex);
                lock (gate)
                    if (!disposed && generation == ticket)
                    { running = null; Publish(StoreBrowserState.Failed, snapshot.Catalog, null, failure.Code,failure.Diagnostic,failure.Diagnostic); }
            }

catch (Exception ex)
                {
                    audit.Failure("install.cleanup_failed",operation.ToString(),ex,"InstallationCleanupFailed");
                    lock (gate) if (!disposed && generation == ticket)
                        Publish(snapshot.State, snapshot.Catalog, snapshot.Plan, "InstallationCleanupRequired",
                            "Temporary cleanup failed; unknown files were preserved. Inspect the installation audit transaction before retrying.", repository: snapshot.Repository);
                }

catch(Exception error)
            {
                // A faulty cancellation callback cannot retain the worker admission slot.
                try { repositoryLog?.Invoke("Store cancellation callback failed: "+error.GetType().Name); } catch { }
            }

catch (Exception error)
            {
                try { Shutdown(hostContext); }
                catch (Exception cleanup) { throw new AggregateException(error, cleanup); }
                throw;
            }

catch (Exception ex)
            {
                log?.Invoke(new LogEventArgs(
                    $"[PhinixDefaultTradeBehaviour] onTradeCreationSuccess threw: {ex}",
                    LogLevel.ERROR));
            }

catch (Exception ex)
            {
                log?.Invoke(new LogEventArgs(
                    $"[PhinixDefaultTradeBehaviour] onTradeCreationFailure threw: {ex}",
                    LogLevel.ERROR));
            }

catch (Exception ex)
            {
                log?.Invoke(new LogEventArgs(
                    $"[PhinixDefaultTradeBehaviour] depositCompletion threw: {ex}",
                    LogLevel.ERROR));
            }

catch (Exception ex)
            {
                if(pending.ReconciliationOnly)
                {
                    // This immutable receive scope cannot become valid on a later save.
                    // Keep Received/Unbound evidence and report once, without repeated retries/stacks.
                    log?.Invoke(new LogEventArgs("[Trade] Delivery retained for reconciliation: "+pending.HoldMessageKey+"; trade="+pending.Args.TradeId,LogLevel.WARNING));
                    if(notifyFailure)notifyDeliveryFailure(pending.HoldMessageKey,string.Empty);
                    return;
                }
                log?.Invoke(new LogEventArgs(
                    $"[Trade] Delivery did not complete for '{pending.Args.TradeId}'; retained for reconciliation: {ex}",
                    LogLevel.ERROR));
                if (notifyFailure)
                    notifyDeliveryFailure("Phinix_trade_inventoryDepositFailed",ex.Message);
            }

catch (Exception ex)
            {
                log?.Invoke(new LogEventArgs(
                    $"[PhinixDefaultTradeBehaviour] onTradeUpdateFailure threw: {ex}",
                    LogLevel.ERROR));
            }

catch(Exception error)
            {
                CompletionFailure?.Invoke(error.GetType().Name);
                log?.Invoke(new LogEventArgs("[Trade] Completion payload retained without delivery: "+error,LogLevel.ERROR));
                return;
            }

catch (Exception exception)
                {
                    if (poppedThing?.Thing != null && !poppedThing.Thing.Destroyed)
                    {
                        unrestoredThings.Add(poppedThing.Thing);
                    }

                    log?.Invoke(
                        $"[{context}] Failed to restore a transferred thing.{Environment.NewLine}{exception}",
                        LogLevel.ERROR);
                }

catch (System.Exception exception)
                            {
                                log?.Invoke(
                                    $"[StackedThings] Failed to compare stackability for thing '{item.ThingID}'; using an isolated stack.{System.Environment.NewLine}{exception}",
                                    LogLevel.WARNING);
                            }

catch (System.Exception exception)
            {
                log?.Invoke(
                    $"[StackedThings] Item enumeration failed; returning the groups collected so far.{System.Environment.NewLine}{exception}",
                    LogLevel.WARNING);
            }

catch (Exception exception)
            {
                LogFailure(log, "Failed to enumerate maps while collecting tradable items.", exception);
                return collectedThings;
            }

catch (Exception exception)
            {
                LogFailure(log, $"Failed to enumerate all things on map '{map}'.", exception);
            }

catch (Exception exception)
            {
                LogFailure(log, $"Failed to enumerate storage groups on map '{map}'; using map-level fallback.", exception);
                CollectStoredMapItemsFallback(map, collectedThings, collectedThingIds, collectedUnassignedThings, log);
                return;
            }

catch (Exception exception)
                {
                    fallbackRequired = true;
                    LogFailure(
                        log,
                        $"Failed to enumerate storage group {groupIndex} on map '{map}'; the group was isolated.",
                        exception);
                }

catch (Exception exception)
            {
                LogFailure(log, $"Failed to snapshot things for storage fallback on map '{map}'.", exception);
                return;
            }

catch (Exception exception)
                {
                    failedPredicates++;
                    firstFailure = firstFailure ?? exception;
                }

catch (Exception error)
            {
                try { Dispose(); }
                catch (Exception cleanup) { throw new AggregateException(error, cleanup); }
                throw;
            }

catch (Exception error)
            {
                try { Dispose(); }
                catch (Exception cleanup) { throw new AggregateException(error, cleanup); }
                throw;
            }

catch (Exception exception)
            {
                throw new InvalidOperationException($"The entire trade update was rejected because item encoding failed (codec '{codec?.CodecId ?? "unresolved"}').", exception);
            }

catch (Exception exception)
            {
                if (string.Equals(payload?.CodecId, StatefulTradeItemProtocol.ScribeCodecId, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException("Stateful trade item decoding failed; delivery was rejected to prevent item-state loss.", exception);
                }
                codecContext.Log?.Invoke($"Failed to decode item payload with codec '{codec.CodecId}': {exception.Message}", LogLevel.WARNING);
                return buildUnknownItem(payload?.CodecId ?? codec.CodecId);
            }

catch (Exception exception)
            {
                DiscardUnclaimed(things);
                return new InventoryDeliveryResult
                {
                    Status = InventoryDeliveryStatus.Rejected,
                    Reason = "Trade items could not be restored without loss: " + exception.Message
                };
            }

catch (InvalidOperationException)
            {
                if (item?.StatePayload != null && item.StatePayload.Length > 0)
                {
                    throw;
                }
                return CreateUnknownItem(item);
            }

catch(Exception error)
                    {
                        // Submission has not invoked business work. Keep this page,
                        // but report once until a submission succeeds.
                        if(!submissionFailureReported){submissionFailureReported=true;failure="Recovery scheduling failed: "+error.GetType().Name;}
                    }

catch (Exception error)
                    {
                        // Storage failures must not masquerade as successful migration.
                        if (error is ClientDatabaseException) { Dispose(); throw; }
                        database.Write((c,t) => DatabaseSql.Execute(c,t,"INSERT OR IGNORE INTO trade_legacy_imports VALUES($b,$n,NULL,$p)","$b",bucket,"$n",name,"$p",error.GetType().Name));
                        warning?.Invoke("Historical trade record could not be imported; its file is retained. " + error.GetType().Name);
                    }

catch(Exception error)
            {
                if(token!=null)clientHostContext.OfferOperations.AbortBeforeSend(token);
                editorNotice=L("editorPreparationFailed");
                hostContext.Log(new LogEventArgs("Trade offer preparation failed: "+error,LogLevel.ERROR));
            }

catch (Exception exception)
            {
                clearPendingAccepted();
                hostContext.Log(new LogEventArgs($"Failed to send trade status update for trade '{trade.TradeId}': {exception.Message}", LogLevel.ERROR));
            }

catch (Exception exception)
            {
                hostContext.Log(new LogEventArgs($"Failed to send trade cancel request for trade '{trade.TradeId}': {exception.Message}", LogLevel.ERROR));
            }

catch (Exception exception)
                    {
                        hostContext.Log(new LogEventArgs(
                            $"[TradeWindow] Inventory entry '{entry.EntryId}' cannot be offered: {exception}",
                            LogLevel.WARNING));
                    }

catch (Exception ex)
            {
                RaiseLogEntry(new LogEventArgs(
                    $"Failed to read incoming packet from peer {peer.ConnectId:X}: {ex.Message}",
                    LogLevel.ERROR));
                return;
            }

